class Pipeline:
    def __init__(self, steps):
        self.steps = steps

    def fit_transform(self, arr):
        data = arr
        for transformer in self.steps:
            data = transformer.fit_transform(data)
        return data

    def transform(self, arr):
        data = arr
        for transformer in self.steps:
            data = transformer.transform(data)
        return data
